  --success: #47e6a0;
  --info: #b08cff;
  --bg-dark: #080907;
  --tone-bg: #080907;
  --tone-main-light: #ff8a3d;
  --tone-main-rgba: rgba(255, 138, 61, 0.22);
  --tone-main-x: 50%;
  --tone-main-y: 18%;
  --tone-soft-light: #54d9ff;
  --tone-soft-rgba: rgba(84, 217, 255, 0.22);
  --tone-soft-x: 82%;
  --tone-soft-y: 78%;
  --subtitle-color: #ffffff;
  --subtitle-active-color: #ff8a3d;
  --subtitle-font-size: 72px;
  --subtitle-bottom: 120px;
}

/* Variables only: a composition that reads them restyles itself, one that
   hard-codes its captions keeps its own design until "Take over caption
   styling" is switched on. */
.caption,
.subtitle,
[data-hf-caption],
[data-subtitle] {
  color: var(--subtitle-color);
  font-size: var(--subtitle-font-size);
  bottom: var(--subtitle-bottom);
}

